/* PlaneChaser service worker.
 *
 * Hand-rolled rather than generated by next-pwa: STATE.md flagged
 * @ducanh2912/next-pwa's App Router/Next 16 compatibility as an unverified
 * blocker, and the caching this app actually needs is narrow enough that a
 * build-step dependency isn't worth it.
 *
 * Strategy:
 *   - Immutable media (Scryfall card art, Supabase public storage, local
 *     audio, icons) -> cache-first, capped. This is the whole point: card
 *     images should survive spotty wifi at the table.
 *   - Navigations -> network-first, falling back to the cached page and then
 *     to /offline.html.
 *   - Everything else (Supabase REST/Realtime/auth, /api/*, RSC payloads)
 *     -> straight to network, never cached. Caching authenticated API
 *     responses on a device players pass around would leak between accounts.
 */

const VERSION = 'v1'
const MEDIA_CACHE = `planechaser-media-${VERSION}`
const PAGE_CACHE = `planechaser-pages-${VERSION}`
const OFFLINE_URL = '/offline.html'

// Cap the media cache so a long campaign can't fill the device.
const MEDIA_MAX_ENTRIES = 300

const MEDIA_HOSTS = ['cards.scryfall.io']
const MEDIA_PATH_PREFIXES = ['/audio/', '/icons/']

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(PAGE_CACHE)
      .then((cache) => cache.add(OFFLINE_URL))
      .then(() => self.skipWaiting())
  )
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys
            .filter((key) => key.startsWith('planechaser-') && !key.endsWith(VERSION))
            .map((key) => caches.delete(key))
        )
      )
      .then(() => self.clients.claim())
  )
})

function isMediaRequest(url) {
  if (MEDIA_HOSTS.includes(url.hostname)) return true
  // Supabase public storage objects (custom plane art) are immutable too.
  if (url.hostname.endsWith('.supabase.co') && url.pathname.startsWith('/storage/v1/object/public/')) {
    return true
  }
  if (url.origin === self.location.origin) {
    return MEDIA_PATH_PREFIXES.some((prefix) => url.pathname.startsWith(prefix))
  }
  return false
}

async function trimCache(cacheName, maxEntries) {
  const cache = await caches.open(cacheName)
  const keys = await cache.keys()
  if (keys.length <= maxEntries) return
  // Caches are roughly insertion-ordered; drop the oldest overflow.
  await Promise.all(keys.slice(0, keys.length - maxEntries).map((key) => cache.delete(key)))
}

async function cacheFirst(request) {
  const cache = await caches.open(MEDIA_CACHE)
  const cached = await cache.match(request)
  if (cached) return cached

  const response = await fetch(request)
  // Opaque (no-cors) responses are fine to store for images; errors are not.
  if (response && (response.ok || response.type === 'opaque')) {
    await cache.put(request, response.clone())
    trimCache(MEDIA_CACHE, MEDIA_MAX_ENTRIES)
  }
  return response
}

async function networkFirstPage(request) {
  const cache = await caches.open(PAGE_CACHE)
  try {
    const response = await fetch(request)
    if (response && response.ok) {
      await cache.put(request, response.clone())
    }
    return response
  } catch {
    const cached = await cache.match(request)
    if (cached) return cached
    const offline = await cache.match(OFFLINE_URL)
    if (offline) return offline
    throw new Error('offline and no cached page available')
  }
}

self.addEventListener('fetch', (event) => {
  const { request } = event

  // Never touch non-GET: auth, conquest writes and game-state syncs must fail
  // loudly rather than be served from a cache.
  if (request.method !== 'GET') return

  let url
  try {
    url = new URL(request.url)
  } catch {
    return
  }

  if (url.protocol !== 'http:' && url.protocol !== 'https:') return

  // Same-origin API routes stay uncached.
  if (url.origin === self.location.origin && url.pathname.startsWith('/api/')) return

  // Supabase REST / Realtime / auth: always live.
  if (url.hostname.endsWith('.supabase.co') && !isMediaRequest(url)) return

  if (isMediaRequest(url)) {
    event.respondWith(cacheFirst(request))
    return
  }

  if (request.mode === 'navigate') {
    event.respondWith(networkFirstPage(request))
  }
})
